sksl:
uniform shader image;
uniform float2 size;
uniform float time;
layout(color) uniform half4 key;
uniform float tolerance;
uniform float softness;
uniform float invert;
float2 chroma(half3 c) { return float2(-0.1687 * c.r - 0.3313 * c.g + 0.5 * c.b, 0.5 * c.r - 0.4187 * c.g - 0.0813 * c.b); }
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    float d = distance(chroma(unpremul(c).rgb), chroma(key.rgb));
    float keep = smoothstep(tolerance, tolerance + softness + 0.0001, d);
    return c * half(invert > 0.5 ? 1.0 - keep : keep);
}
